// lib/openapi.ts
import { openApiRouter } from "@asteasolutions/zod-to-openapi";
import { createPostSchema, postSchema } from "@/lib/validators/post";

const router = openApiRouter();

router.register(
  {
    method: "post",
    path: "/api/posts",
    summary: "Create a post",
    request: { body: { content: { "application/json": { schema: createPostSchema } } } },
    responses: { 201: { body: { content: { "application/json": { schema: postSchema } } } } },
  }
);

export const openApiDocument = router.generate();
